func TestExecuteSelectedContractRunForkAdmitsSameSourceActiveDeliveryForkPointEmission(t *testing.T) {
	_, db, _ := testutil.StartPostgres(t)
	pg := storetest.AdmitPostgresRuntimeStore(t, db)
	ctx := runForkTestContext(t)
	repoRoot := runForkExecutionRepoRoot(t)
	contractsRoot := filepath.Join(repoRoot, "tests/tier1-primitives/test-emits-multiple")
	platformSpecPath := runtimecontracts.DefaultPlatformSpecFile(repoRoot)
	loader := admittedFixtureSelectedContractSourceLoader{RepoRoot: repoRoot, SourceRoot: contractsRoot, PlatformSpecPath: platformSpecPath}
	loaded, err := loader.LoadRunForkSelectedContractSource(ctx, runfork.RunForkContractSelection{Mode: "selected_contracts"})
	if err != nil {
		t.Fatalf("LoadRunForkSelectedContractSource: %v", err)
	}
	sourceRunID := uuid.NewString()
	entityID := uuid.NewString()
	sourceEventID := uuid.NewString()
	forkPointEventID := uuid.NewString()
	sessionID := uuid.NewString()
	auditID := uuid.NewString()
	turnID := uuid.NewString()
	at := time.Unix(1700002303, 0).UTC()
	forkAt := at.Add(30 * time.Second)
	agentRoute := selectedExecutionTestAgentRoute(t, sourceRunID, "validation-coordinator", "flow-a/1")
	entityID = sourceRunID
	sourceEvent := seedSelectedConstructedRootHistory(t, ctx, pg, loaded, sourceRunID, sourceEventID, "item.received", at, executionmode.Live, []events.DeliveryRoute{selectedConstructedRootNodeRoute(loaded.Source, sourceRunID, "test-node"), agentRoute})
	agentIdentity := agentRoute.AgentIdentity
	agentFields := selectedExecutionTestAgentFields(t, agentIdentity)
	processCapability := seedSelectedExecutionTestAgent(t, ctx, pg, agentIdentity, at, loaded.SourceArtifactFact)
	if _, err := db.ExecContext(ctx, `
		INSERT INTO agent_sessions (
			session_id, run_id, agent_id, agent_name_owner, agent_name_source,
			agent_route_presence, flow_scope_key, flow_instance_id, flow_instance, memory_enabled,
			status, created_at, updated_at
		)
		VALUES ($1::uuid, $2::uuid, $3, $4, $5, $6, $7, $8, $9, TRUE,
			'active', $10, $10)
	`, sessionID, sourceRunID, agentFields.AgentID, agentFields.NameOwner, agentFields.NameSource, agentFields.RoutePresence, agentFields.FlowScopeKey, agentFields.FlowInstanceID, agentFields.FlowInstancePath, at); err != nil {
		t.Fatalf("seed source session: %v", err)
	}
	if _, err := db.ExecContext(ctx, `
		INSERT INTO agent_conversation_audits (
			session_id, run_id, agent_id, agent_name_owner, agent_name_source,
			agent_route_presence, flow_scope_key, flow_instance_id, entity_id, flow_instance, memory_enabled,
			runtime_state, status, created_at, updated_at
		)
		VALUES ($1::uuid, $2::uuid, $3, $4, $5, $6, $7, $8, $9::uuid, $10, FALSE,
			'{}'::jsonb, 'active', $11, $11)
	`, auditID, sourceRunID, agentFields.AgentID, agentFields.NameOwner, agentFields.NameSource, agentFields.RoutePresence, agentFields.FlowScopeKey, agentFields.FlowInstanceID, entityID, agentFields.FlowInstancePath, at); err != nil {
		t.Fatalf("seed source conversation audit: %v", err)
	}
	turnEvent := storetest.InsertNativeExistingRunRootEvent(t, ctx, pg, uuid.NewString(), sourceRunID, "turn.fixture", eventtest.Producer(events.EventProducerExternal, "run-fork-turn-fixture"), []byte(`{}`), events.EventEnvelope{}, at)
	persistRunForkManagedTurn(t, ctx, pg, turnEvent, agentIdentity, sourceRunID, sessionID, turnID, entityID, at)
	claimed, err := storetest.ClaimDelivery(ctx, pg, sourceEvent, agentRoute)
	if err != nil {
		t.Fatalf("claim in-progress source delivery: %v", err)
	}
	if claimed.Snapshot.ActiveSessionID != "" {
		t.Fatalf("in-progress source delivery active session = %q, want unbound #678 lineage case", claimed.Snapshot.ActiveSessionID)
	}
	storetest.InsertUnrevisionedChildEventRecord(t, ctx, pg, forkPointEventID, sourceRunID, sourceEventID, "item.received", eventtest.Producer(events.EventProducerAgent, "validation-coordinator"), []byte(`{}`), events.EnvelopeForFlowInstance(events.EnvelopeForEntityID(events.EventEnvelope{}, entityID), "flow-a/1"), forkAt)
	captureSelectedExecutionSourceRevision(t, pg, sourceRunID)
	result, err := executeLiveSelectedContractRunFork(ctx, SelectedContractExecutionRequest{SourceRunID: sourceRunID, At: forkPointEventID, AllowSourceFreeze: true, Owner: selectedContractExecutionOwnerWithProcessForTest(t, pg, processCapability), SourceLoader: loader, ContractSelection: runforkadmission.SelectedContractSelection(loaded.Source), AgentRuntime: SelectedContractAgentRuntimeOptions{ProcessCapability: processCapability}})
	if err != nil {
		t.Fatalf("ExecuteSelectedContractRunFork: %v", err)
	}
	if result.Materialization.ForkRunID == "" || !result.Activation.Activated {
		t.Fatalf("selected execution result = %#v", result)
	}
	for _, code := range []string{runfork.RunForkBlockerDeliveryHistoryUnproven, runfork.RunForkBlockerSessionHistoryUnproven, runfork.RunForkBlockerConversationAuditUnproven, runfork.RunForkBlockerActiveTurnHistoryUnproven} {
		if selectedExecutionResultHasBlocker(result, code) {
			t.Fatalf("selected execution retained %s: materialization=%#v activation=%#v", code, result.Materialization.UnsupportedBlockers, result.Activation.UnsupportedBlockers)
		}
	}
	if !result.Activation.SourceAdvancedAfterFork || result.Activation.BranchDivergence == nil || !containsString(result.Activation.BranchDivergence.SourceAdvancedFacts, runfork.RunForkSelectedContractActiveSourceDeliveryConversationCouplingClassification) {
		t.Fatalf("activation branch divergence = %#v, want #678 same-source active delivery fact", result.Activation.BranchDivergence)
	}
	var copiedSessions, copiedAudits, copiedTurns, copiedSourceSubscriberDeliveries int
	if err := db.QueryRowContext(ctx, `
		SELECT COUNT(*) FROM agent_sessions WHERE run_id = $1::uuid OR session_id = $2::uuid
	`, result.Materialization.ForkRunID, sessionID).Scan(&copiedSessions); err != nil {
		t.Fatalf("count session copies: %v", err)
	}
	if err := db.QueryRowContext(ctx, `
		SELECT COUNT(*) FROM agent_conversation_audits WHERE run_id = $1::uuid OR session_id = $2::uuid
	`, result.Materialization.ForkRunID, auditID).Scan(&copiedAudits); err != nil {
		t.Fatalf("count audit copies: %v", err)
	}
	if err := db.QueryRowContext(ctx, `
		SELECT COUNT(*) FROM agent_turns WHERE run_id = $1::uuid OR turn_id = $2::uuid
	`, result.Materialization.ForkRunID, turnID).Scan(&copiedTurns); err != nil {
		t.Fatalf("count turn copies: %v", err)
	}
	if err := db.QueryRowContext(ctx, `
		SELECT COUNT(*)
		FROM event_deliveries
		WHERE run_id = $1::uuid
		  AND subscriber_id = 'validation-coordinator'
		  AND status = 'in_progress'
	`, result.Materialization.ForkRunID).Scan(&copiedSourceSubscriberDeliveries); err != nil {
		t.Fatalf("count copied source delivery: %v", err)
	}
	if copiedSessions != 1 || copiedAudits != 1 || copiedTurns != 1 || copiedSourceSubscriberDeliveries != 0 {
		t.Fatalf("copied source rows sessions=%d audits=%d turns=%d sourceDeliveries=%d, want source-only conversation rows and no source delivery copies", copiedSessions, copiedAudits, copiedTurns, copiedSourceSubscriberDeliveries)
	}
}

